// Sidebar документации Latent.
//
// Явно описаны разделы, за которые отвечает docs-guide (intro,
// getting-started, tutorial, guide). Разделы reference/specs/tooling/examples
// пишет docs-reference, поэтому они подключены через `type: 'autogenerated'` —
// категория появляется автоматически, как только в каталоге появятся файлы.
//
// Локализация: sidebar id одинаковы для всех локалей; переводы подписей
// категорий/элементов лежат в i18n/<locale>/docusaurus-plugin-content-docs/.
//
// Устойчивость к незавершённому контенту: id, для которого ещё нет файла
// (например, web-and-frontend пишет параллельный агент), просто выпадает из
// sidebar — сборка не падает, а после появления файла пункт подхватится сам.

const fs = require('node:fs');
const path = require('node:path');

/** Проверяет, что каталог с документами существует. */
function dirExists(dirName) {
  return fs.existsSync(path.join(__dirname, 'docs', dirName));
}

/** Проверяет, что markdown/mdx-файл документа существует (.md, .mdx). */
function docExists(id) {
  const base = path.join(__dirname, 'docs', id);
  return (
    fs.existsSync(base + '.md') ||
    fs.existsSync(base + '.mdx') ||
    fs.existsSync(path.join(base, 'index.md')) ||
    fs.existsSync(path.join(base, 'index.mdx'))
  );
}

/** Оставляет только существующие id; отсутствующие страницы не ломают сборку. */
function existing(ids) {
  return ids.filter(docExists);
}

/**
 * Возвращает autogenerated-категорию, если каталог уже существует.
 * Когда в каталог добавят файлы, категория подхватится сама.
 */
function autogenerated(dirName) {
  return dirExists(dirName) ? {type: 'autogenerated', dirName} : null;
}

const guideItems = existing([
  'guide/index',
  'guide/syntax',
  'guide/variables-and-types',
  'guide/operators',
  'guide/control-flow',
  'guide/functions',
  'guide/arrays-and-strings',
  'guide/classes',
  'guide/enums-and-pattern-matching',
  'guide/lambdas-and-closures',
  'guide/error-handling',
  'guide/concurrency',
  'guide/ai-features',
  'guide/testing-and-contracts',
  'guide/memory-and-low-level',
  'guide/wasm-and-execution',
  // Новые веб/фронтенд-темы (файлы пишет frontend-content).
  'guide/web-and-frontend',
  // Файловые модули: import/export, линковка, bundle (v1).
  'guide/modules',
  // Killer-фичи: обзор того, за счёт чего язык выигрывает у JS/TS.
  'guide/killer-features',
]);

// numberPrefixParser: false (docusaurus.config.js) — id сохраняют числовые
// префиксы: 01-hello-world.md → tutorial/01-hello-world, URL
// /tutorial/01-hello-world.
const tutorialItems = existing([
  'tutorial/index',
  'tutorial/01-hello-world',
  'tutorial/02-variables-and-types',
  'tutorial/03-operators-and-control-flow',
  'tutorial/04-functions-and-recursion',
  'tutorial/05-arrays-and-strings',
  'tutorial/06-classes',
  'tutorial/07-enums-and-match',
  'tutorial/08-lambdas-and-higher-order',
  'tutorial/09-tests-and-contracts',
  'tutorial/10-capstone',
]);

const gettingStartedItems = existing([
  'getting-started/install',
  'getting-started/hello-world',
  'getting-started/cli',
  'getting-started/web-ide',
  // Новая тема: запуск Latent в браузере (файл пишет frontend-content).
  'getting-started/web-browser',
]);

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  docs: [
    {
      type: 'category',
      label: 'Введение',
      collapsed: false,
      items: existing(['index', 'intro/why-latent', 'intro/philosophy', 'intro/comparison']),
    },
    {
      type: 'category',
      label: 'Начало работы',
      collapsed: false,
      items: gettingStartedItems,
    },
    {
      type: 'category',
      label: 'Туториал',
      collapsed: false,
      items: tutorialItems,
    },
    {
      type: 'category',
      label: 'Руководство по языку',
      collapsed: false,
      items: guideItems,
    },
    // Разделы, которые пишет docs-reference. Добавляются, когда каталог есть.
    autogenerated('reference'),
    autogenerated('specs'),
    autogenerated('tooling'),
    autogenerated('examples'),
  ].filter(Boolean),
};

module.exports = sidebars;
